import React from 'react';
import { Button } from '../../ui';
import {
  jobsService,
  type MissingLedgerRepostReviewPreview,
} from '../../services/jobs';
import { SearchInput, useAppToast } from '@linm-soft-org/linm-web-common-components';
import {
  useMissingLedgerRepostVoucherSearchConfig,
} from './useMissingLedgerRepostVoucherSearchConfig';
import type { VoucherRegistryPrefixRow } from '../../services/system/voucherRegistryModels';

type Props = {
  legacyRepostPaused?: boolean;
  onRunStarted?: (runId: string) => void;
  onCompleted?: () => void;
};

const MissingLedgerRepostReviewPanel: React.FC<Props> = ({ legacyRepostPaused, onRunStarted, onCompleted }) => {
  const toast = useAppToast();
  const [fromDate, setFromDate] = React.useState('');
  const [toDate, setToDate] = React.useState('');
  const [prefixCode, setPrefixCode] = React.useState('');
  const [prefixLabel, setPrefixLabel] = React.useState('');
  const [detailVoucherCode, setDetailVoucherCode] = React.useState('');
  const [forceRepost, setForceRepost] = React.useState(false);
  const [preview, setPreview] = React.useState<MissingLedgerRepostReviewPreview | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [running, setRunning] = React.useState(false);
  const [searched, setSearched] = React.useState(false);

  const { config: prefixSearchConfig, loading: prefixConfigLoading } =
    useMissingLedgerRepostVoucherSearchConfig();

  const effectiveVoucherCode = React.useMemo(() => {
    const detail = detailVoucherCode.trim();
    if (detail) return detail;
    return prefixCode.trim();
  }, [detailVoucherCode, prefixCode]);

  const loadPreview = React.useCallback(() => {
    setLoadingPreview(true);
    setSearched(true);
    jobsService
      .getMissingLedgerRepostReviewPreview(fromDate || null, toDate || null, effectiveVoucherCode || null, forceRepost)
      .then(setPreview)
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPreview(false));
  }, [fromDate, toDate, effectiveVoucherCode, forceRepost, toast]);

  const handleRun = React.useCallback(() => {
    if (!searched || !preview) {
      toast.info('Bấm Tìm trước để quét chứng từ thiếu ghi sổ.');
      return;
    }
    if (!preview.totalEligible) {
      toast.info(
        effectiveVoucherCode
          ? `Bộ lọc «${effectiveVoucherCode}» không có chứng từ${forceRepost ? ' đã GL' : ' thiếu GL'} đủ điều kiện.`
          : forceRepost
            ? 'Không có chứng từ đã ghi sổ trong khoảng ngày đã chọn.'
            : 'Không có chứng từ thiếu ghi sổ trong khoảng ngày đã chọn.',
      );
      return;
    }
    const filterLine = effectiveVoucherCode
      ? `\nLọc: ${effectiveVoucherCode}${detailVoucherCode.trim() ? ' (mã chi tiết)' : prefixCode ? ' (prefix danh mục)' : ''}`
      : '';
    const modeLine = forceRepost
      ? 'Repost force (unpost GL + ghi lại)'
      : 'Ghi sổ thiếu GL';
    if (
      !window.confirm(
        `${modeLine} — ${preview.totalEligible.toLocaleString('vi-VN')} chứng từ?${filterLine}\n\n` +
          `HĐ công nợ: ${preview.salesInvoiceReceivableCount.toLocaleString('vi-VN')} ` +
          `(0đ: ${preview.salesInvoiceZeroAmountCount.toLocaleString('vi-VN')}) · ` +
          `PT/PC: ${preview.cashVoucherCount.toLocaleString('vi-VN')} ` +
          `(PT ${preview.cashReceiptCount.toLocaleString('vi-VN')} · PC ${preview.cashPaymentCount.toLocaleString('vi-VN')})`,
      )
    ) {
      return;
    }

    setRunning(true);
    jobsService
      .triggerMissingLedgerRepostReview({
        fromDate: fromDate || null,
        toDate: toDate || null,
        voucherCode: effectiveVoucherCode || null,
        forceRepost,
      })
      .then((result) => {
        if (result.runId) {
          toast.info(
            `Đã tạo job ${forceRepost ? 'repost force' : 'ghi sổ thiếu GL'} — HĐ ${result.invoicesEnqueued.toLocaleString('vi-VN')} · PT/PC ${result.vouchersEnqueued.toLocaleString('vi-VN')} — run ${result.runId.slice(0, 8)}… · theo dõi checkpoint hoặc Job events.`,
          );
          onRunStarted?.(result.runId);
          loadPreview();
          onCompleted?.();
          return;
        }
        toast.success(
          `Đã lên lịch — HĐ ${result.invoicesEnqueued.toLocaleString('vi-VN')} · PT/PC ${result.vouchersEnqueued.toLocaleString('vi-VN')}`,
        );
        loadPreview();
        onCompleted?.();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRunning(false));
  }, [
    preview,
    searched,
    fromDate,
    toDate,
    effectiveVoucherCode,
    detailVoucherCode,
    prefixCode,
    forceRepost,
    toast,
    loadPreview,
    onCompleted,
    onRunStarted,
  ]);

  const resetPreview = React.useCallback(() => {
    setPreview(null);
    setSearched(false);
  }, []);

  const handleDateChange = React.useCallback(
    (field: 'from' | 'to', value: string) => {
      if (field === 'from') setFromDate(value);
      else setToDate(value);
      resetPreview();
    },
    [resetPreview],
  );

  const handlePrefixChange = React.useCallback(
    (item: VoucherRegistryPrefixRow) => {
      setPrefixCode(item.idCodePrefix);
      setPrefixLabel(`${item.idCodePrefix} — ${item.name}`);
      resetPreview();
    },
    [resetPreview],
  );

  const handlePrefixClear = React.useCallback(() => {
    setPrefixCode('');
    setPrefixLabel('');
    resetPreview();
  }, [resetPreview]);

  const handleDetailChange = React.useCallback(
    (value: string) => {
      setDetailVoucherCode(value);
      resetPreview();
    },
    [resetPreview],
  );

  return (
    <div
      style={{
        marginBottom: 16,
        padding: '12px 16px',
        border: '1px solid #cbd5e1',
        borderRadius: 8,
        background: legacyRepostPaused ? '#f1f5f9' : '#eff6ff',
        opacity: legacyRepostPaused ? 0.85 : 1,
      }}
      data-testid="missing-ledger-repost-review-panel"
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div style={{ flex: '1 1 320px' }}>
          <strong>Tự review thiếu ghi sổ (theo khoảng ngày / loại CT)</strong>
          <p style={{ margin: '4px 0 0', color: '#64748b', fontSize: 13 }}>
            Quét HĐ POS chưa GL (hoặc <strong>đã GL</strong> khi bật repost force) và PT/PC <code>FM-*</code>. Chọn{' '}
            <strong>prefix</strong> từ Thiết lập chứng từ — hoặc nhập <strong>mã chi tiết sync</strong> (vd.{' '}
            <code>FM-HD-…</code>) riêng.
          </p>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8, alignItems: 'flex-end' }}>
            <label style={{ fontSize: 13 }}>
              Từ ngày{' '}
              <input
                type="date"
                value={fromDate}
                onChange={(e) => handleDateChange('from', e.target.value)}
                data-testid="missing-ledger-review-from-date"
              />
            </label>
            <label style={{ fontSize: 13 }}>
              Đến ngày{' '}
              <input
                type="date"
                value={toDate}
                onChange={(e) => handleDateChange('to', e.target.value)}
                data-testid="missing-ledger-review-to-date"
              />
            </label>
            <div style={{ flex: '1 1 200px', minWidth: 180 }} data-testid="missing-ledger-review-prefix-search">
              {prefixSearchConfig ? (
                <SearchInput
                  config={prefixSearchConfig}
                  value={prefixCode}
                  primaryDisplay={prefixLabel || prefixCode}
                  label="Loại chứng từ (prefix)"
                  placeholder="INV · PT · PC…"
                  showSecondaryInput={false}
                  disabled={prefixConfigLoading}
                  onChange={handlePrefixChange}
                  onClear={handlePrefixClear}
                />
              ) : (
                <label style={{ fontSize: 13, display: 'block' }}>
                  Loại chứng từ (prefix)
                  <input
                    type="text"
                    disabled
                    placeholder={prefixConfigLoading ? 'Đang tải danh mục…' : 'Chưa có đăng ký CT'}
                    style={{ display: 'block', marginTop: 4, width: '100%' }}
                  />
                </label>
              )}
            </div>
            <label style={{ fontSize: 13, flex: '1 1 200px', minWidth: 180 }}>
              Mã chi tiết (sync)
              <input
                type="text"
                value={detailVoucherCode}
                onChange={(e) => handleDetailChange(e.target.value)}
                placeholder="FM-HD-… / INV-2025…"
                style={{ display: 'block', marginTop: 4, width: '100%' }}
                data-testid="missing-ledger-review-detail-code"
              />
            </label>
            <label
              style={{
                fontSize: 13,
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                alignSelf: 'center',
                cursor: 'pointer',
              }}
              data-testid="missing-ledger-review-force-repost"
            >
              <input
                type="checkbox"
                checked={forceRepost}
                onChange={(e) => {
                  setForceRepost(e.target.checked);
                  resetPreview();
                }}
              />
              Repost force (đã có GL — unpost + ghi lại)
            </label>
          </div>
          {loadingPreview ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>Đang quét…</p>
          ) : preview && searched ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>
              {effectiveVoucherCode ? (
                <>
                  Lọc <strong>{effectiveVoucherCode}</strong>
                  {detailVoucherCode.trim() ? ' (chi tiết)' : ' (prefix)'}
                  {preview.totalEligible ? ' — đủ điều kiện' : ' — không đủ điều kiện'}
                  {' · '}
                </>
              ) : null}
              {forceRepost ? (
                <>
                  Chế độ: <strong>repost force (đã GL)</strong>
                  {' · '}
                </>
              ) : null}
              Tổng đủ điều kiện: <strong>{preview.totalEligible.toLocaleString('vi-VN')}</strong>
              {' — '}
              HĐ <strong>{preview.salesInvoiceReceivableCount.toLocaleString('vi-VN')}</strong>
              {preview.salesInvoiceZeroAmountCount > 0
                ? ` (0đ: ${preview.salesInvoiceZeroAmountCount.toLocaleString('vi-VN')})`
                : ''}
              {' · '}
              PT/PC <strong>{preview.cashVoucherCount.toLocaleString('vi-VN')}</strong>
              {' '}
              (PT {preview.cashReceiptCount.toLocaleString('vi-VN')} · PC {preview.cashPaymentCount.toLocaleString('vi-VN')})
              {preview.sampleInvoiceCodes.length > 0
                ? ` — HĐ ví dụ: ${preview.sampleInvoiceCodes.slice(0, 2).join(', ')}`
                : ''}
              {preview.sampleVoucherCodes.length > 0
                ? ` · PT ví dụ: ${preview.sampleVoucherCodes.slice(0, 2).join(', ')}`
                : ''}
            </p>
          ) : (
            <p style={{ margin: '6px 0 0', fontSize: 13, color: '#64748b' }}>
              Chọn prefix hoặc nhập mã chi tiết (tùy chọn), khoảng ngày rồi bấm Tìm.
            </p>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <Button
            type="button"
            variant="secondary"
            onClick={loadPreview}
            disabled={loadingPreview || running}
            data-testid="missing-ledger-review-search"
          >
            Tìm
          </Button>
          <Button
            type="button"
            onClick={handleRun}
            disabled={
              running ||
              loadingPreview ||
              !searched ||
              !preview?.totalEligible ||
              legacyRepostPaused
            }
            data-testid="missing-ledger-review-trigger"
          >
            {running
              ? 'Đang tạo job…'
              : forceRepost
                ? effectiveVoucherCode
                  ? 'Repost force theo bộ lọc'
                  : 'Repost force'
                : effectiveVoucherCode
                  ? 'Ghi sổ theo bộ lọc'
                  : 'Ghi sổ thiếu GL'}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default MissingLedgerRepostReviewPanel;
