import React from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { navigateInAppPath } from '../../router/navigateInAppPath';
import {
  EXTERNAL_SYNC_JOB_VIEW_META,
  EXTERNAL_SYNC_JOB_VIEW_ORDER,
  resolveExternalSyncJobView,
  type ExternalSyncJobView,
} from './externalSyncJobTypes';

const tabStyle = (active: boolean): React.CSSProperties => ({
  display: 'inline-block',
  padding: '8px 14px',
  borderRadius: 6,
  fontSize: 13,
  fontWeight: active ? 600 : 500,
  textDecoration: 'none',
  color: active ? '#1d4ed8' : '#475569',
  background: active ? '#eff6ff' : '#f8fafc',
  border: active ? '1px solid #93c5fd' : '1px solid #e2e8f0',
  cursor: 'pointer',
  fontFamily: 'inherit',
});

const ExternalSyncActionNav: React.FC = () => {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const activeView = resolveExternalSyncJobView(pathname);

  return (
    <nav
      style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginBottom: 16 }}
      data-testid="external-sync-action-nav"
      aria-label="Thao tác sync REVA"
      role="tablist"
    >
      {EXTERNAL_SYNC_JOB_VIEW_ORDER.map((view: ExternalSyncJobView) => {
        const meta = EXTERNAL_SYNC_JOB_VIEW_META[view];
        const isActive = activeView === view;
        return (
          <button
            key={view}
            type="button"
            role="tab"
            aria-selected={isActive}
            style={tabStyle(isActive)}
            data-testid={`external-sync-nav-${view}`}
            onClick={() => navigateInAppPath(meta.path, navigate)}
          >
            {meta.shortLabel}
          </button>
        );
      })}
    </nav>
  );
};

export default ExternalSyncActionNav;
