import type {
  DataSyncRunDetail,
  DataSyncRunListItem,
  ExternalSyncErrorSample,
} from '../../services/jobs/dataSyncModels';

export const EXTERNAL_CONNECTOR_LABELS: Record<string, string> = {
  'reva-fm-hoa-don': 'Hóa đơn bán',
  'reva-fm-phieu-thu': 'Phiếu thu',
  'reva-fm-phieu-chi': 'Phiếu chi',
  'pos-vat-refill': 'Re-fill VAT HĐ POS',
  'missing-ledger-repost-review': 'Review thiếu ghi sổ',
  'legacy-cash-voucher-repost': 'Ghi sổ PT/PC sync cũ',
  'legacy-sales-invoice-receivable-repost': 'Ghi sổ HĐ CONGNO',
};

export const connectorLabel = (configKey: string): string =>
  EXTERNAL_CONNECTOR_LABELS[configKey] ?? configKey;

const GUID_LIKE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** Ẩn companyCode nếu BE lưu nhầm Guid tenant thay vì mã công ty. */
export const formatExternalRunCompanyLabel = (
  companyCode?: string | null,
  companyName?: string | null,
): string | null => {
  const code = companyCode?.trim();
  if (!code || GUID_LIKE.test(code)) return companyName?.trim() || null;
  return companyName?.trim() ? `${code} · ${companyName.trim()}` : code;
};

export const resolveExternalRunDisplayStatus = (run: {
  status: string;
  progressPercent?: number;
  documentsConverted?: number;
  documentsSkipped?: number;
  checkpointSummary?: { failed: number; pending?: number; processing?: number; total?: number };
}): string => {
  const failed = run.checkpointSummary?.failed ?? 0;
  const pending = run.checkpointSummary?.pending ?? 0;
  const processing = run.checkpointSummary?.processing ?? 0;
  const inFlight = pending + processing;
  const converted = run.documentsConverted ?? 0;
  const skipped = run.documentsSkipped ?? 0;
  const total =
    (run.checkpointSummary?.total ?? 0) > 0
      ? (run.checkpointSummary?.total ?? 0)
      : converted + skipped + failed;
  const hasCheckpointWork = total > 0 || failed > 0;

  if (run.status === 'Running' && inFlight === 0 && hasCheckpointWork) {
    return failed > 0 ? 'Partial' : 'Success';
  }

  if (
    run.status === 'Running'
    && inFlight === 0
    && (run.progressPercent ?? 0) >= 100
    && converted > 0
  ) {
    return failed > 0 ? 'Partial' : 'Success';
  }

  if (run.checkpointSummary && failed > 0 && run.status === 'Success') {
    return 'Partial';
  }

  return run.status;
};

export const resolveExternalRunListDisplayStatus = (run: DataSyncRunListItem): string =>
  resolveExternalRunDisplayStatus({
    status: run.status,
    progressPercent: run.progressPercent,
    documentsConverted: run.documentsConverted,
    documentsSkipped: run.documentsSkipped,
    checkpointSummary: {
      failed: run.documentsFailed ?? 0,
      pending: run.checkpointPending ?? 0,
      processing: run.checkpointProcessing ?? 0,
      total: run.documentsTotal ?? 0,
    },
  });

export const formatExternalRunStatsLine = (run: DataSyncRunDetail | DataSyncRunListItem): string => {
  const summary = 'conversionSummary' in run ? run.conversionSummary : undefined;
  const converted = run.documentsConverted ?? summary?.documentsConverted ?? 0;
  const checkpointFailed =
    'checkpointSummary' in run ? run.checkpointSummary?.failed ?? 0 : 0;
  const failed = Math.max(
    run.documentsFailed ?? summary?.documentsFailed ?? 0,
    checkpointFailed,
  );
  const total =
    summary?.documentsTotal ??
    run.documentsTotal ??
    ('checkpointSummary' in run ? run.checkpointSummary?.total : 0) ??
    0;
  const pullOnly = summary?.documentsPullOnly ?? 0;
  const skipped = summary?.documentsSkipped ?? run.documentsSkipped ?? 0;

  const parts: string[] = [`${converted.toLocaleString('vi-VN')} mới`];
  if (skipped > 0) {
    parts.push(`${skipped.toLocaleString('vi-VN')} đã có`);
  }
  if (failed > 0) {
    parts.push(`${failed.toLocaleString('vi-VN')} lỗi`);
  }
  if (total > 0) {
    parts.push(`${total.toLocaleString('vi-VN')} tổng`);
  }
  return parts.join(' · ');
};

/** Giữ bản lỗi mới nhất theo mã chứng từ (retry có thể ghi nhiều sample). */
export const dedupeExternalErrorSamples = (
  samples: ExternalSyncErrorSample[] | undefined,
): ExternalSyncErrorSample[] => {
  const byKey = new Map<string, ExternalSyncErrorSample>();
  for (const sample of samples ?? []) {
    const key = sample.documentKey?.trim() || sample.message.trim() || `__${byKey.size}`;
    const existing = byKey.get(key);
    if (!existing) {
      byKey.set(key, sample);
      continue;
    }
    const sampleAt = sample.atUtc ? Date.parse(sample.atUtc) : 0;
    const existingAt = existing.atUtc ? Date.parse(existing.atUtc) : 0;
    if (sampleAt >= existingAt) {
      byKey.set(key, sample);
    }
  }
  return [...byKey.values()];
};

export const formatCheckpointSummaryHint = (summary: {
  total: number;
  done: number;
  skipped: number;
  failed: number;
  pending: number;
  processing: number;
}): string => {
  const parts = [`${summary.total.toLocaleString('vi-VN')} checkpoint`];
  if (summary.done > 0) parts.push(`${summary.done.toLocaleString('vi-VN')} mới`);
  if (summary.skipped > 0) parts.push(`${summary.skipped.toLocaleString('vi-VN')} đã có`);
  if (summary.failed > 0) parts.push(`${summary.failed.toLocaleString('vi-VN')} lỗi`);
  if (summary.processing > 0) parts.push(`${summary.processing.toLocaleString('vi-VN')} Processing`);
  if (summary.pending > 0) parts.push(`${summary.pending.toLocaleString('vi-VN')} Pending`);
  return parts.join(' · ');
};

export const buildErrorMessageMap = (
  samples: DataSyncRunDetail['errorSamples'],
  checkpoints?: Array<{ documentKey: string; errorMessage?: string | null }>,
): Map<string, string> => {
  const map = new Map<string, string>();
  for (const sample of samples ?? []) {
    if (sample.documentKey) {
      map.set(sample.documentKey, sample.message);
    }
  }
  for (const cp of checkpoints ?? []) {
    if (cp.documentKey && cp.errorMessage && !map.has(cp.documentKey)) {
      map.set(cp.documentKey, cp.errorMessage);
    }
  }
  return map;
};

/** Pin run from detail API when list page does not include it (deep link / pagination). */
export const runDetailToListItem = (detail: DataSyncRunDetail): DataSyncRunListItem => ({
  id: detail.id,
  companyId: detail.companyId,
  companyCode: detail.companyCode,
  companyName: detail.companyName,
  status: detail.status,
  trigger: detail.trigger,
  environmentName: detail.environmentName,
  kind: detail.kind,
  startedAtUtc: detail.startedAtUtc,
  finishedAtUtc: detail.finishedAtUtc,
  setsRequested: detail.setsRequested,
  progressPercent: detail.progressPercent,
  documentsConverted: detail.conversionSummary?.documentsConverted,
  documentsSkipped: detail.conversionSummary?.documentsSkipped,
  documentsTotal:
    detail.conversionSummary?.documentsTotal ?? detail.checkpointSummary?.total,
  documentsFailed:
    detail.conversionSummary?.documentsFailed ?? detail.checkpointSummary?.failed ?? 0,
});
