import React from 'react';
import { Button } from '../../../ui';
import { jobsService, type LegacySalesInvoiceReceivableRepostPreview } from '../../../services/jobs';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';

type Props = {
  legacyRepostPaused?: boolean;
  onRunStarted: (runId: string) => void;
};

const ExternalSyncLegacyInvoicePanel: React.FC<Props> = ({ legacyRepostPaused, onRunStarted }) => {
  const toast = useAppToast();
  const [fromDate, setFromDate] = React.useState('');
  const [toDate, setToDate] = React.useState('');
  const [preview, setPreview] = React.useState<LegacySalesInvoiceReceivableRepostPreview | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [running, setRunning] = React.useState(false);
  const [searched, setSearched] = React.useState(false);

  const loadPreview = React.useCallback(() => {
    setLoadingPreview(true);
    setSearched(true);
    jobsService
      .getLegacySalesInvoiceReceivableRepostPreview(fromDate || null, toDate || null)
      .then(setPreview)
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPreview(false));
  }, [fromDate, toDate, toast]);

  const handleDateChange = React.useCallback((field: 'from' | 'to', value: string) => {
    if (field === 'from') setFromDate(value);
    else setToDate(value);
    setPreview(null);
    setSearched(false);
  }, []);

  const handleRun = React.useCallback(() => {
    if (legacyRepostPaused) {
      toast.warning('Ghi sổ batch đang tạm dừng — bỏ tick «Tạm dừng ghi sổ batch».');
      return;
    }
    if (!searched || !preview?.eligibleCount) {
      toast.info('Bấm Tìm trước — không có HĐ POS thiếu sổ công nợ trong khoảng đã chọn.');
      return;
    }
    const range =
      fromDate || toDate ? `\nKhoảng ngày HĐ: ${fromDate || '…'} → ${toDate || '…'}` : '';
    const ok = window.confirm(
      `Ghi sổ công nợ ${preview.eligibleCount.toLocaleString('vi-VN')} HĐ POS (Draft · chưa có GL trên HĐ)?` + range,
    );
    if (!ok) return;

    setRunning(true);
    jobsService
      .triggerLegacySalesInvoiceReceivableRepost({ fromDate: fromDate || null, toDate: toDate || null })
      .then((result) => {
        if (result.runId) {
          toast.info(
            `Đã tạo job ghi sổ ${result.documentsEnqueued.toLocaleString('vi-VN')} HĐ — theo dõi run bên dưới.`,
          );
          onRunStarted(result.runId);
          return;
        }
        toast.success(`Đã lên lịch ${result.documentsEnqueued.toLocaleString('vi-VN')} HĐ.`);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRunning(false));
  }, [legacyRepostPaused, searched, preview, fromDate, toDate, toast, onRunStarted]);

  return (
    <div
      style={{
        marginBottom: 16,
        padding: '12px 16px',
        border: '1px solid #e2e8f0',
        borderRadius: 8,
        background: legacyRepostPaused ? '#f1f5f9' : '#f8fafc',
        opacity: legacyRepostPaused ? 0.85 : 1,
      }}
      data-testid="legacy-sales-invoice-repost-panel"
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div style={{ flex: '1 1 280px' }}>
          <strong>Ghi sổ HĐ POS thiếu công nợ (CONGNO)</strong>
          <p style={{ margin: '4px 0 0', color: '#64748b', fontSize: 13 }}>
            HĐ <code>FM-HD-*</code> · Draft · chưa có dòng sổ trên HĐ — Nợ 131 · Có 511.
          </p>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8, alignItems: 'center' }}>
            <label style={{ fontSize: 13 }}>
              Từ ngày{' '}
              <input type="date" value={fromDate} onChange={(e) => handleDateChange('from', e.target.value)} data-testid="invoice-repost-from-date" />
            </label>
            <label style={{ fontSize: 13 }}>
              Đến ngày{' '}
              <input type="date" value={toDate} onChange={(e) => handleDateChange('to', e.target.value)} data-testid="invoice-repost-to-date" />
            </label>
          </div>
          {loadingPreview ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>Đang đếm…</p>
          ) : preview && searched ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>
              Đủ điều kiện: <strong>{preview.eligibleCount.toLocaleString('vi-VN')}</strong>
              {preview.zeroAmountEligibleCount > 0
                ? ` (0đ: ${preview.zeroAmountEligibleCount.toLocaleString('vi-VN')})`
                : ''}
            </p>
          ) : (
            <p style={{ margin: '6px 0 0', fontSize: 13, color: '#64748b' }}>Chọn khoảng ngày HĐ và bấm Tìm.</p>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <Button type="button" variant="secondary" onClick={loadPreview} disabled={loadingPreview || running} data-testid="invoice-repost-refresh">
            Tìm
          </Button>
          <Button
            type="button"
            onClick={handleRun}
            disabled={running || loadingPreview || !searched || !preview?.eligibleCount || legacyRepostPaused}
            data-testid="invoice-repost-trigger"
          >
            {running ? 'Đang tạo job…' : 'Ghi sổ HĐ thiếu CN'}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default ExternalSyncLegacyInvoicePanel;
